compute:
const rev = Number(revenue) || 0;
const opex = Number(operatingExpenses) || 0;
const da = Number(depreciationAmortization) || 0;
const it = Number(interestAndTax) || 0;
const ebitda = rev - opex;
const ebit = ebitda - da;
const netIncome = ebit - it;
const ebitdaMargin = rev > 0 ? (ebitda / rev) * 100 : 0;
return { ebitdaMargin, ebitda, ebit, netIncome };

